#!/usr/bin/env python
from __future__ import annotations

import argparse
from contextlib import redirect_stdout
from io import StringIO
import json
from pathlib import Path
import sys
from typing import Any

from hsconfig.cli import main
from hsconfig.configure_workflow import (
    _load_validated_optimized_start_selection,
    _optimized_start_selection_summary,
)
from hsconfig.package_request import FrozenJsonDocument


_CANDIDATES = (
    ("candidate-1.json", "candidate-1", "proactive_tempo"),
    ("candidate-2.json", "candidate-2", "balanced"),
    ("candidate-3.json", "candidate-3", "resource_oriented"),
)
_CONTROLLED_FLAGS = (
    "--apply",
    "--candidate-json",
    "--json",
    "--optimized-start",
    "--starter-context-json",
    "--starter-decision-json",
)
_NON_REPEATABLE_OPTIONS = frozenset(
    {
        *_CONTROLLED_FLAGS,
        "--cards-json",
        "--claims-json",
        "--collectible-cards-json",
        "--current-date",
        "--deck-code",
        "--deck-name",
        "--full-cards-json",
        "--guide-sources-json",
        "--out",
        "--plan-reports-dir",
        "--runtime-root",
        "--source-documents-json",
        "--source-evidence-json",
        "--source-fixture-url-map-json",
        "--source-search-results-json",
        "--starter-dir",
    }
)
_RECEIPT_FIELDS = frozenset(
    {
        "candidate_id",
        "candidate_revision",
        "content_sha256",
        "runtime_intent_sha256",
        "starter_context_sha256",
        "strategy_role",
        "valid",
    }
)


def _contains_flag(arguments: list[str], flag: str) -> bool:
    for value in arguments:
        option = value.partition("=")[0]
        if option == flag or (option.startswith("--") and flag.startswith(option)):
            return True
    return False


def _option_count(arguments: list[str], flag: str) -> int:
    return sum(
        value.partition("=")[0] == flag for value in arguments if value.startswith("--")
    )


def _ambiguous_option(arguments: list[str]) -> str | None:
    for value in arguments:
        option = value.partition("=")[0]
        if not option.startswith("--") or option in _NON_REPEATABLE_OPTIONS:
            continue
        if any(flag.startswith(option) for flag in _NON_REPEATABLE_OPTIONS):
            return option
    return None


def _parse() -> tuple[argparse.ArgumentParser, argparse.Namespace, list[str]]:
    parser = argparse.ArgumentParser(
        description=(
            "Deterministic optimized-start helper; never writes runtime files."
        ),
        allow_abbrev=False,
    )
    parser.add_argument(
        "phase",
        choices=("starter-context", "validate-candidates", "configure"),
    )
    parser.add_argument("--starter-dir", required=True)
    arguments = sys.argv[1:]
    ambiguous = _ambiguous_option(arguments)
    if ambiguous is not None:
        parser.error(f"ambiguous option prefix {ambiguous}")
    for flag in _NON_REPEATABLE_OPTIONS:
        if _option_count(arguments, flag) > 1:
            parser.error(f"duplicate option {flag}")
    namespace, forwarded = parser.parse_known_args(arguments)
    forbidden = list(_CONTROLLED_FLAGS)
    if namespace.phase == "starter-context":
        forbidden.append("--out")
    for flag in forbidden:
        if _contains_flag(forwarded, flag):
            parser.error(f"helper controls {flag}")
    if namespace.phase == "validate-candidates" and forwarded:
        parser.error("validate-candidates accepts no forwarded arguments")
    return parser, namespace, forwarded


def _strict_json_object(raw: str, *, error: str) -> dict[str, Any]:
    try:
        value = FrozenJsonDocument.from_json_bytes(raw.encode("utf-8")).to_value()
    except (TypeError, UnicodeError, ValueError) as cause:
        raise ValueError(error) from cause
    if not isinstance(value, dict):
        raise ValueError(error)
    return value


def _capture_json_command(
    arguments: list[str],
    *,
    error: str,
) -> tuple[int, dict[str, Any] | None]:
    output = StringIO()
    with redirect_stdout(output):
        result = main(arguments)
    raw = output.getvalue()
    if result != 0:
        if raw:
            print(raw, end="")
        return result, None
    return 0, _strict_json_object(raw, error=error)


def _sha256_value(value: object) -> bool:
    return (
        isinstance(value, str)
        and value.startswith("sha256:")
        and len(value) == 71
        and all(character in "0123456789abcdef" for character in value[7:])
    )


def _validate_candidate_receipts(
    receipts: list[dict[str, Any]],
) -> None:
    if len(receipts) != len(_CANDIDATES):
        raise ValueError("starter_candidate_receipt_set_invalid")
    for receipt, (_filename, candidate_id, role) in zip(
        receipts,
        _CANDIDATES,
        strict=True,
    ):
        if (
            set(receipt) != _RECEIPT_FIELDS
            or receipt.get("valid") is not True
            or receipt.get("candidate_id") != candidate_id
            or receipt.get("strategy_role") != role
            or type(receipt.get("candidate_revision")) is not int
            or receipt["candidate_revision"] < 1
            or not _sha256_value(receipt.get("content_sha256"))
            or not _sha256_value(receipt.get("runtime_intent_sha256"))
            or not _sha256_value(receipt.get("starter_context_sha256"))
        ):
            raise ValueError("starter_candidate_receipt_set_invalid")
    for field in (
        "candidate_id",
        "content_sha256",
        "runtime_intent_sha256",
    ):
        if len({receipt[field] for receipt in receipts}) != 3:
            raise ValueError("starter_candidate_receipt_set_invalid")
    if len({receipt["starter_context_sha256"] for receipt in receipts}) != 1:
        raise ValueError("starter_candidate_receipt_set_invalid")


def _expected_optimized_projection(starter_dir: Path) -> dict[str, Any]:
    try:
        selection = _load_validated_optimized_start_selection(starter_dir)
        return _optimized_start_selection_summary(selection)
    except (KeyError, OSError, TypeError, ValueError) as cause:
        raise ValueError("optimized_start_summary_invalid") from cause


def _emit_json(value: object) -> None:
    print(
        json.dumps(
            value,
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        )
    )


def _run() -> int:
    parser, namespace, forwarded = _parse()
    starter_dir = Path(namespace.starter_dir)
    context = starter_dir / "starter_context.json"
    if namespace.phase == "starter-context":
        if starter_dir.exists():
            parser.error("external starter directory must be initially absent")
        return main(
            [
                "starter-context",
                *forwarded,
                "--out",
                str(starter_dir),
                "--json",
            ]
        )
    if namespace.phase == "validate-candidates":
        receipts: list[dict[str, Any]] = []
        for filename, _candidate_id, _role in _CANDIDATES:
            result, receipt = _capture_json_command(
                [
                    "starter-validate-candidate",
                    "--starter-context-json",
                    str(context),
                    "--candidate-json",
                    str(starter_dir / filename),
                    "--json",
                ],
                error="starter_candidate_receipt_set_invalid",
            )
            if result != 0:
                return result
            if receipt is None:
                raise ValueError("starter_candidate_receipt_set_invalid")
            receipts.append(receipt)
        _validate_candidate_receipts(receipts)
        _emit_json(receipts)
        return 0

    expected = _expected_optimized_projection(starter_dir)
    result, summary = _capture_json_command(
        [
            "configure",
            *forwarded,
            "--optimized-start",
            "--starter-decision-json",
            str(starter_dir / "starter_config_decision.json"),
            "--json",
        ],
        error="optimized_start_summary_invalid",
    )
    if result != 0:
        return result
    if summary is None or summary.get("optimized_start") != expected["optimized_start"]:
        raise ValueError("optimized_start_summary_invalid")
    _emit_json(summary)
    return 0


raise SystemExit(_run())
